import {removeSearchParams, updateUrl} from '@github-ui/history'

export type TabType = 'configurations' | 'repositories'

const DEFAULT_TAB: TabType = 'configurations'

/**
 * Encapsulates tab, query, and page URL state for the security products page.
 *
 * Rules (see spec.md):
 * - `q` and `page` are scoped to the repositories tab and omitted from the URL on the configurations tab.
 * - If `q` is present in the URL without an explicit `tab`, the tab is inferred as `repositories`.
 * - Invalid or missing `tab` values fall back to `configurations` (unless `q` is present).
 */
export class QueryState {
  tab: TabType
  query: string
  page: number

  constructor(tab: TabType = DEFAULT_TAB, query = '', page = 1) {
    this.tab = tab
    this.query = query
    this.page = page
  }

  toURLSearchParams = (): URLSearchParams => {
    const params: Record<string, string> = {}

    // Only include tab when it's not the default (configurations)
    if (this.tab !== DEFAULT_TAB) {
      params.tab = this.tab
    }

    // q and page are scoped to the repositories tab
    if (this.tab === 'repositories') {
      if (this.query) params.q = this.query
      if (this.page !== 1) params.page = this.page.toString()
    }

    return new URLSearchParams(params)
  }

  /**
   * Returns only the repo-scoped params (q, page) for building API fetch URLs.
   * This preserves the interface that RepositorySection / fetchData expect.
   */
  toRepoSearchParams = (): URLSearchParams => {
    const params = new URLSearchParams()
    if (this.query) params.set('q', this.query)
    if (this.page !== 1) params.set('page', this.page.toString())
    return params
  }

  toString = (): string => {
    return this.toRepoSearchParams().toString()
  }

  static restoreFromSearchParams = (searchParams: URLSearchParams): QueryState => {
    const rawTab = searchParams.get('tab')
    const query = searchParams.get('q') || ''
    const page = parseInt(searchParams.get('page') || '1')

    let tab: TabType
    if (rawTab === 'configurations' || rawTab === 'repositories') {
      tab = rawTab
    } else if (query) {
      // No valid tab param, but q implies repositories
      tab = 'repositories'
    } else {
      // Default
      tab = DEFAULT_TAB
    }

    return new QueryState(tab, query, page)
  }

  persistToHistory = (): void => {
    const params = this.toURLSearchParams()
    const queryString = params.toString()
    if (queryString) {
      updateUrl(`?${queryString}`)
    } else {
      removeSearchParams()
    }
  }
}
