import {useMemo} from 'react'
import {PickerListBody} from '@github-ui/filter-picker'
import {RepoIcon, RepoLockedIcon, OrganizationIcon, AlertIcon, ArchiveIcon} from '@primer/octicons-react'
import {FormControl, Checkbox, Spinner, Truncate, Flash} from '@primer/react'
import {Filter} from '@github-ui/filter'
import type {FilterQuery, SubmitEvent} from '@github-ui/filter-core'
import {Blankslate} from '@primer/react/experimental'
import {getAllStaticProviders} from '@github-ui/repos-filter/providers'
import type {Repository, RepositoryPickerState} from '../../security-products-enablement-types'
import {SecurityConfigurationStatus} from '../../security-products-enablement-types'
import styles from './RepositoriesStep.module.css'

// Note The org job will also only process up to 500 repositories per configuration
const MAX_REPOSITORY_SELECTION = 500

const LoadingState = () => (
  <Blankslate>
    <Blankslate.Visual>
      <Spinner size="medium" />
    </Blankslate.Visual>
    <Blankslate.Description>Loading repositories...</Blankslate.Description>
  </Blankslate>
)

const ErrorState = () => (
  <Blankslate>
    <Blankslate.Visual>
      <AlertIcon size={24} className={styles.errorIcon} />
    </Blankslate.Visual>
    <Blankslate.Heading>We couldn&apos;t load the repositories</Blankslate.Heading>
    <Blankslate.Description>Try again, or if the problem persists, contact support.</Blankslate.Description>
  </Blankslate>
)

const EmptyState = () => (
  <Blankslate>
    <Blankslate.Heading>No repositories found</Blankslate.Heading>
    <Blankslate.Description>Use a different query.</Blankslate.Description>
  </Blankslate>
)

interface RepositoriesStepProps {
  selectedRepoIds: Set<number>
  onSelectionChange: (ids: Set<number>) => void
  repositoryPicker: RepositoryPickerState
  /** Optional UI transition state (e.g., dialog step transition) - combined with repositoryPicker.isLoading */
  isTransitioning?: boolean
  /** The ID of the configuration being edited (used to detect failed attachments) */
  configurationId?: number
}

export function RepositoriesStep({
  selectedRepoIds,
  onSelectionChange,
  repositoryPicker,
  isTransitioning = false,
  configurationId,
}: RepositoriesStepProps) {
  const {
    org,
    repositories,
    reposById,
    totalCount,
    isLoading: isDataLoading,
    isError,
    filterValue,
    onFilterChange,
  } = repositoryPicker
  // Combine data loading state with UI transition state
  const isLoading = isDataLoading || isTransitioning

  const visibleRepoIds = useMemo(() => {
    if (isLoading || isError) return new Set<number>()
    return new Set(repositories.map(repo => repo.id))
  }, [repositories, isLoading, isError])

  const visibleRepos = useMemo(() => {
    if (isLoading || isError) return []
    return repositories
  }, [repositories, isLoading, isError])

  const noVisibleRepos = visibleRepos.length === 0

  const selectedRepos = useMemo(() => {
    const result: Repository[] = []
    for (const selectedRepoId of selectedRepoIds) {
      const selectedRepo = reposById.get(selectedRepoId)
      if (selectedRepo) result.push(selectedRepo)
    }
    return result
  }, [reposById, selectedRepoIds])

  const noSelectedRepos = selectedRepoIds.size === 0

  const hiddenSelectedCount = useMemo(() => {
    if (isLoading || isError) return 0
    return Array.from(selectedRepoIds).filter(id => !visibleRepoIds.has(id)).length
  }, [visibleRepoIds, selectedRepoIds, isLoading, isError])

  const isAtSelectionLimit = selectedRepoIds.size >= MAX_REPOSITORY_SELECTION

  const isSelectAllChecked = useMemo(() => {
    if (noVisibleRepos || noSelectedRepos) return false
    for (const visibleRepo of visibleRepos) {
      if (!selectedRepoIds.has(visibleRepo.id)) return false
    }
    return true
  }, [visibleRepos, noVisibleRepos, selectedRepoIds, noSelectedRepos])

  const isSelectAllIndeterminate = useMemo(() => {
    if (isSelectAllChecked || noVisibleRepos || noSelectedRepos) return false
    for (const visibleRepo of visibleRepos) {
      if (selectedRepoIds.has(visibleRepo.id)) return true
    }
    return false
  }, [isSelectAllChecked, visibleRepos, noVisibleRepos, selectedRepoIds, noSelectedRepos])

  const handleSelectAll = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.checked) {
      // Add all visible repos to selection, but respect the limit
      const newSelection = new Set(selectedRepoIds)
      for (const repo of visibleRepos) {
        if (newSelection.size >= MAX_REPOSITORY_SELECTION) break
        newSelection.add(repo.id)
      }
      onSelectionChange(newSelection)
    } else {
      // Remove all visible repos from selection
      const newSelection = new Set(selectedRepoIds)
      for (const repo of visibleRepos) {
        newSelection.delete(repo.id)
      }
      onSelectionChange(newSelection)
    }
  }

  const handleSelectionChange = (repos: Repository[]) => {
    const newSelection = new Set(repos.map(r => r.id))

    // Also preserve any hidden selections (repos not in current view)
    for (const id of selectedRepoIds) {
      if (!visibleRepoIds.has(id)) {
        newSelection.add(id)
      }
    }

    // Enforce selection limit
    if (newSelection.size > MAX_REPOSITORY_SELECTION) {
      // Don't allow adding more than the limit
      return
    }

    onSelectionChange(newSelection)
  }

  const handleFilterSubmit = (_query: FilterQuery, _eventType: SubmitEvent) => {
    // Filter submission is handled by the debounced value in useRepositories
  }

  const providers = useMemo(() => getAllStaticProviders(), [])

  const getBlankView = () => {
    if (isLoading) return <LoadingState />
    if (isError) return <ErrorState />
    if (noVisibleRepos) return <EmptyState />
    return null
  }

  function getRepoIcon(repo: Repository) {
    if (repo.archived) return <ArchiveIcon size={16} />

    switch (repo.visibility) {
      case 'public':
        return <RepoIcon size={16} />
      case 'private':
        return <RepoLockedIcon size={16} />
      case 'internal':
        return <OrganizationIcon size={16} />
      default:
        return <RepoIcon size={16} />
    }
  }

  function getRepoName(repo: Repository) {
    return (
      <Truncate title={repo.name} className={styles.repositoryName}>
        {repo.name}
      </Truncate>
    )
  }

  function getRepoDescription(repo: Repository) {
    if (repo.archived) {
      return <span className="Label Label--secondary">Archived</span>
    }
    return null
  }

  function getRepoTrailingVisual(repo: Repository) {
    const secConfig = repo.security_configuration
    if (!secConfig) return null

    if (
      configurationId &&
      secConfig.status === SecurityConfigurationStatus.Failed &&
      secConfig.security_configuration_id === configurationId
    ) {
      return <span className="color-fg-muted">Failed attachment</span>
    }
    return null
  }

  return (
    <div className={styles.repositorySelectionContainer}>
      {isAtSelectionLimit && (
        <Flash variant="warning" className={styles.selectionLimitWarning}>
          Maximum {MAX_REPOSITORY_SELECTION} repositories can be selected. Deselect some repositories to select others
          or apply it to more repositories from the Repositories tab.
        </Flash>
      )}
      <div className={styles.stickyHeader}>
        <div className={styles.filterContainer}>
          <Filter
            id="repository-filter"
            label="Filter repositories"
            variant="input"
            filterValue={filterValue}
            onChange={onFilterChange}
            onSubmit={handleFilterSubmit}
            providers={providers}
            context={{org}}
            aria-label="Filter repositories using available filters"
            aria-describedby="filter-help-text"
          />
          <div id="filter-help-text" className="sr-only">
            Filter repositories using text search or available filters
          </div>
        </div>
        {!noVisibleRepos && (
          <FormControl className={styles.selectAllControl}>
            <Checkbox
              checked={isSelectAllChecked}
              indeterminate={isSelectAllIndeterminate}
              onChange={handleSelectAll}
              disabled={isAtSelectionLimit && !isSelectAllChecked}
            />
            <FormControl.Label>Select all</FormControl.Label>
          </FormControl>
        )}
      </div>
      <div className={styles.repositoryListContainer}>
        <PickerListBody
          hiddenSelectedCount={hiddenSelectedCount}
          isFiltered={hiddenSelectedCount > 0}
          blankMessage={getBlankView()}
          totalItemsCount={totalCount}
          selectionVariant="multiple"
          items={visibleRepos}
          selectedItems={selectedRepos}
          setSelectedItems={(repos: Repository[]) => {
            // Check if this would exceed the limit
            const wouldExceed = repos.length + hiddenSelectedCount > MAX_REPOSITORY_SELECTION
            if (wouldExceed && repos.length > selectedRepos.length) {
              // Trying to add more, but would exceed limit - don't allow
              return
            }
            handleSelectionChange(repos)
          }}
          title="Select repositories"
          onRenderItemName={getRepoName}
          onRenderItemLeadingVisual={getRepoIcon}
          onRenderItemDescription={getRepoDescription}
          onRenderItemTrailingVisual={getRepoTrailingVisual}
        />
      </div>
    </div>
  )
}
