import type React from 'react'
import {Link as PrimerLink, Banner as PrimerBanner} from '@primer/react'
import {Link} from '@github-ui/react-core/link'
import {clsx} from 'clsx'

import styles from './Banner.module.css'

interface BannerProps {
  bannerText: string
  linkText?: string
  linkHref?: string
  dismissible?: boolean
  onDismiss?: () => void
  bannerType?: string
}

const Banner: React.FC<BannerProps> = ({
  bannerText,
  linkText,
  linkHref,
  dismissible = false,
  onDismiss,
  bannerType,
}) => {
  const handleDismiss = () => {
    if (onDismiss) onDismiss()
  }

  return (
    <div data-testid={`banner-${bannerType}`} className={styles.Flash}>
      <PrimerBanner
        title="Information"
        description={
          <span data-testid="banner-text">
            {bannerText}
            {linkText && linkHref && (
              <PrimerLink
                as={Link}
                to={linkHref}
                className={clsx('Link--inTextBlock', styles.PrimerLink)}
                data-testid="banner-link"
              >
                {linkText}
              </PrimerLink>
            )}
          </span>
        }
        variant="info"
        hideTitle
        onDismiss={dismissible ? handleDismiss : undefined}
      />
    </div>
  )
}

export default Banner
