import {Fragment} from 'react'
import {Heading, Text} from '@primer/react'
import {clsx} from 'clsx'
import styles from './UsageSummary.module.css'

export interface UsageSummarySectionData {
  title: string
  percentage: number
  href?: string
  subtext?: string
}

export interface UsageSummaryProps {
  sections: UsageSummarySectionData[]
  className?: string
  testId?: string
}

function UsageSummarySection({
  title,
  percentage,
  href,
  subtext = 'of repositories protected',
}: UsageSummarySectionData) {
  const displayPercentage = Math.round(percentage)
  const percentageContent = (
    <Text className="f3 lh-default" size="medium" weight="normal">
      {displayPercentage}%
    </Text>
  )

  return (
    <div className={styles.section}>
      <Heading as="h2" className="f5">
        {title}
      </Heading>
      {href ? (
        <a
          href={href}
          className={styles.metricLink}
          aria-label={`View ${title} coverage details: ${displayPercentage}% of repositories protected`}
        >
          {percentageContent}
        </a>
      ) : (
        percentageContent
      )}
      <Text className="color-fg-muted" size="small">
        {subtext}
      </Text>
    </div>
  )
}

export function UsageSummary({sections, className, testId = 'usage-summary'}: UsageSummaryProps) {
  if (sections.length === 0) {
    return null
  }

  return (
    <div className={clsx(styles.container, className)} data-testid={testId}>
      {sections.map((section, index) => (
        <Fragment key={section.title}>
          {index > 0 && <div className={styles.divider} />}
          <UsageSummarySection {...section} />
        </Fragment>
      ))}
    </div>
  )
}
