import {Button, Flash, Stack} from '@primer/react'
import {AlertIcon} from '@primer/octicons-react'
import {SkeletonBox} from '@primer/react/experimental'
import pluralize from 'pluralize'
import {QuickSetupApplyTo, QuickSetupDefaultForNewRepos} from '../../security-products-enablement-types'
import styles from './ReviewStep.module.css'

interface ReviewStepProps {
  applyTo: QuickSetupApplyTo
  defaultForNewRepos: QuickSetupDefaultForNewRepos
  repoCount: number
  secretProtectionCount: number
  codeSecurityCount: number
  isSaveError?: boolean
  isLoadingLicenses?: boolean
  isLicensesError?: boolean
  onRetryLicenses?: () => void
}

export function ReviewStep({
  applyTo,
  defaultForNewRepos,
  repoCount,
  secretProtectionCount,
  codeSecurityCount,
  isSaveError = false,
  isLoadingLicenses = false,
  isLicensesError = false,
  onRetryLicenses,
}: ReviewStepProps) {
  const isNotApplicable = applyTo === QuickSetupApplyTo.NotApplicable

  const newReposTextMap: Record<QuickSetupDefaultForNewRepos, string> = {
    [QuickSetupDefaultForNewRepos.All]: ' and all new repositories going forward',
    [QuickSetupDefaultForNewRepos.Public]: ' and all new public repositories going forward',
    [QuickSetupDefaultForNewRepos.Private]: ' and all new private and internal repositories going forward',
    [QuickSetupDefaultForNewRepos.None]: '',
  }

  const newReposText = newReposTextMap[defaultForNewRepos]

  const renderLicenseContent = () => {
    if (isLoadingLicenses) {
      return (
        <Stack direction="vertical" gap="condensed">
          <SkeletonBox height="32px" width="100%" />
          <SkeletonBox height="24px" width="280px" />
          <SkeletonBox height="24px" width="240px" />
        </Stack>
      )
    }

    if (isLicensesError) {
      return (
        <div className={styles.licenseErrorContainer}>
          <AlertIcon size={24} className="color-fg-danger" />
          <div className="color-fg-danger">Failed to load license estimates</div>
          {onRetryLicenses && (
            <Button size="small" variant="invisible" onClick={onRetryLicenses}>
              Try again
            </Button>
          )}
        </div>
      )
    }

    return (
      <>
        <p className={styles.helperText}>
          Based on active committers to private repositories within the last 90 days. Standard bill rate may not apply
          if a coupon or discount is available.
        </p>
        <div className={styles.licenseRow}>
          <span>
            {secretProtectionCount} Secret Protection {pluralize('license', secretProtectionCount)}
          </span>
          <span>$19/month</span>
        </div>
        <div className={styles.licenseRow}>
          <span>
            {codeSecurityCount} Code Security {pluralize('license', codeSecurityCount)}
          </span>
          <span>$30/month</span>
        </div>
      </>
    )
  }

  return (
    <Stack gap="normal">
      {isSaveError ? (
        <Flash variant="danger">Something went wrong saving the configuration. Please try again.</Flash>
      ) : null}

      {/* Description */}
      <div>
        {isNotApplicable ? (
          <>
            These settings will apply to {repoCount} repositories attached to this configuration
            {newReposText} and could incur costs.
          </>
        ) : (
          <>
            These settings will apply to {repoCount} existing repositories
            {newReposText}.
          </>
        )}
      </div>

      {/* License estimates section - hidden for NotApplicable since we can't enumerate repos */}
      {!isNotApplicable && (
        <Stack direction="vertical" gap="none">
          <h3 className={styles.sectionHeader}>Additional estimated licenses</h3>

          {renderLicenseContent()}
        </Stack>
      )}
    </Stack>
  )
}
