import {verifiedFetchJSON} from '@github-ui/verified-fetch'

type StartTrialResponse = {error?: string}
export async function startTrial(advancedSecuritySettingsPath: string): Promise<void> {
  const response = await verifiedFetchJSON(`${advancedSecuritySettingsPath}/trials`, {
    method: 'POST',
  })
  const result = (await response.json()) as StartTrialResponse
  if (!result) {
    throw new Error('Failed to start trial')
  }
  if ('error' in result) {
    throw new Error(result.error)
  }
}
