import {Banner} from '@primer/react'
import type {Capabilities} from '../security-products-enablement-types'

const UsageLockedBanner = ({capabilities, userNamespace}: {capabilities: Capabilities; userNamespace: boolean}) => {
  const advancedSecurityLocked =
    capabilities.advancedSecurity.bundled && capabilities.advancedSecurity.advancedSecurityEnablementLocked
  const secretProtectionLocked =
    !capabilities.advancedSecurity.bundled && capabilities.advancedSecurity.secretProtectionEnablementLocked
  const codeSecurityLocked =
    !capabilities.advancedSecurity.bundled && capabilities.advancedSecurity.codeSecurityEnablementLocked

  if (!advancedSecurityLocked && !secretProtectionLocked && !codeSecurityLocked && !userNamespace) {
    return null
  }

  if (!advancedSecurityLocked && !secretProtectionLocked && userNamespace) {
    return null
  }

  const description = `GitHub Advanced Security features cannot be enabled on additional repositories due to a billing issue. Configurations for existing repositories can be managed as usual. After resolving the issue, please allow a few minutes for changes to apply.`

  return (
    <Banner
      description={description}
      title="Enablement locked for new repositories"
      variant="info"
      data-testid="security-configs-enablement-locked-banner"
      className="tmp-mb-3"
    />
  )
}

export default UsageLockedBanner
