import {useState, useMemo, useCallback} from 'react'
import {Link as PrimerLink, UnderlineNav} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {
  orgOnboardingAdvancedSecurityPath,
  settingsOrgSecurityConfigurationsNewPath,
  settingsOrgSecurityConfigurationsQuickSetupPath,
  settingsEnterpriseSecurityProductsPath,
  settingsOrgSecurityProductsRepositories,
  orgSecurityCoveragePath,
} from '@github-ui/paths'
import {OnboardingTipBanner} from '@github-ui/onboarding-tip-banner'
import {ShieldCheckIcon} from '@primer/octicons-react'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useSearchParams} from '@github-ui/use-navigate'
import {useAlive} from '@github-ui/use-alive'
import {useDebounce} from '@github-ui/use-debounce'
import {verifiedFetch, verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {useAppContext} from '../contexts/AppContext'
import {RepositoryContext} from '../contexts/RepositoryContext'
import {fetchRefresh} from '../utils/api-helpers'
import {dismissNoticePath, dismissBusinessNoticePath, getUpsellBannerNoticeKey} from '../utils/banner-helper'
import {Link} from '@github-ui/react-core/link'
import RepositorySection from '../components/RepositorySection'
import Subhead from '../components/Subhead'
import Banner from '../components/Banner'
import {CopilotSurvey} from '@github-ui/copilot-survey/CopilotSurvey'
import BlankSlate from '../components/BlankSlate'
import SecurityConfigurationTable from '../components/SecurityConfiguration/Table'
import type {OpenQuickSetupOptions} from '../components/SecurityConfiguration/Row'
import {
  type MiniSecurityConfiguration,
  type OrganizationSettingsSecurityProductsPayload,
  type FailureCounts,
  SecurityProductAvailability,
  type Repository,
  type OrganizationLicensePayload,
  type Enterprise,
  type QuickSetupDialogModeType,
} from '../security-products-enablement-types'

import styles from './OrganizationSettingsSecurityProducts.module.css'
import usageSummaryStyles from '../components/EnterpriseSettings/UsageSummary.module.css'
import UsageLockedBanner from '../components/UsageLockedBanner'
import {UsageSummary} from '../components/EnterpriseSettings/UsageSummary'
import {UpsellBanner} from '../components/EnterpriseSettings/UpsellBanner'
import {UpsellCTA} from '../components/EnterpriseSettings/UpsellCTA'
import {useTabQueryState} from '../hooks/use-tab-query-state'
import {COVERAGE_QUERY_FILTER, getDisplayTitle} from '../utils/coverage-helpers'
import {QueryState} from '../utils/query-state'
import {QuickSetupDialog} from '../components/QuickSetup/QuickSetupDialog'
import {QuickSetupDialogMode} from '../security-products-enablement-types'

const OrganizationSettingsSecurityProducts: React.FC = () => {
  const {
    securityProducts,
    organization,
    enterprise,
    enterpriseAdmin,
    docsUrls,
    capabilities,
    githubRecommendedConfiguration: initialGithubRecommendedConfiguration,
    customSecurityConfigurations: initialCustomSecurityConfigurations,
    customEnterpriseSecurityConfigurations: initialCustomEnterpriseSecurityConfigurations,
    enterpriseConfigsAvailable,
  } = useAppContext()
  const [searchParams] = useSearchParams()
  const {
    showInfoBanner: initialShowInfoBanner,
    changesInProgress: changes,
    repositories: initialRepositories,
    channel,
    failureCounts: initialFailureCounts,
    licenses: initialLicenses,
    totalRepositoryCount: initialTotalRepositoryCount,
    pageCount: initialPageCount,
    selfServeBanner: selfServeBanner,
    // Upsell data - only present for enterprise admins
    coverageStats,
    upsellType,
    showUpsellBanner: initialShowUpsellBanner,
    selfServeTrialInfo,
  } = useRoutePayload<OrganizationSettingsSecurityProductsPayload>()

  const isQuickSetupEnabled = capabilities.hasOrganizationQuickSetup === true

  const {activeTab, queryState, switchTab, updateQuery} = useTabQueryState()

  const [quickSetupDialogState, setQuickSetupDialogState] = useState<{
    isOpen: boolean
    dialogMode: QuickSetupDialogModeType
    settingsReadOnly: boolean
    configurationId?: number
    originalAttachedRepoCount?: number
    failedReposCount?: number
  }>({
    isOpen: false,
    dialogMode: QuickSetupDialogMode.NEW,
    settingsReadOnly: false,
  })

  const [changesInProgress, setChangesInProgress] = useState(changes)
  const [repositories, setRepositories] = useState<Repository[]>(initialRepositories)
  const [totalRepositoryCount, setTotalRepositoryCount] = useState(initialTotalRepositoryCount)
  const [showInfoBanner, setShowInfoBanner] = useState(initialShowInfoBanner)

  // Upsell banner visibility state (enterprise admins only)
  const [showUpsellBanner, setShowUpsellBanner] = useState(initialShowUpsellBanner ?? false)

  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const isUsageSummaryEnabled = useFeatureFlag('ghas_config_usage_cards')

  const [githubRecommendedConfiguration, setGithubRecommendedConfiguration] = useState<
    MiniSecurityConfiguration | undefined
  >(initialGithubRecommendedConfiguration)
  const [customSecurityConfigurations, setCustomSecurityConfigurations] = useState<MiniSecurityConfiguration[]>(
    initialCustomSecurityConfigurations,
  )
  const [customEnterpriseSecurityConfigurations, setCustomEnterpriseSecurityConfigurations] = useState<
    MiniSecurityConfiguration[]
  >(initialCustomEnterpriseSecurityConfigurations)
  const [failureCounts, setFailureCounts] = useState<FailureCounts>(initialFailureCounts)

  const [pageCount, setPageCount] = useState(initialPageCount ?? 1)
  const [flashBannerType, setFlashBannerType] = useState<string | null>(null)
  const [isQueryLoading, setIsQueryLoading] = useState<boolean>(false)

  // Fetch repository data from the API and update state.
  // Returns true on success, false on failure. Does not manage loading state or URL.
  const fetchRepositories = useCallback(
    async (params: URLSearchParams) => {
      const url = `${settingsOrgSecurityProductsRepositories({org: organization})}?${params}`
      const result = await verifiedFetchJSON(url, {method: 'GET'})

      if (result.ok) {
        const resultJson = await result.json()
        setRepositories(resultJson.repositories)
        setTotalRepositoryCount(resultJson.totalRepositoryCount)
        setPageCount(resultJson.pageCount)
        return true
      }
      return false
    },
    [organization],
  )

  // Silently refresh repository data without updating the browser URL.
  // Used by background refreshes (Alive events, dialog close).
  const refreshRepositories = useCallback(
    (state: QueryState) => fetchRepositories(state.toRepoSearchParams()),
    [fetchRepositories],
  )

  // Search repositories AND update the browser URL.
  // Used for user-initiated actions (search, pagination, filter clicks).
  const searchRepositories = useCallback(
    async (query: string, page: number) => {
      const newState = updateQuery(query, page)
      setIsQueryLoading(true)

      try {
        const ok = await fetchRepositories(newState.toRepoSearchParams())
        if (!ok) setFlashBannerType('searchTimedout')
      } finally {
        setIsQueryLoading(false)
      }
    },
    [fetchRepositories, updateQuery],
  )

  const configs: MiniSecurityConfiguration[] = useMemo(
    () => [
      ...(githubRecommendedConfiguration ? [githubRecommendedConfiguration] : []),
      ...customEnterpriseSecurityConfigurations,
      ...customSecurityConfigurations,
    ],
    [githubRecommendedConfiguration, customEnterpriseSecurityConfigurations, customSecurityConfigurations],
  )

  const hasNoConfigs = useMemo(
    () =>
      Boolean(
        customSecurityConfigurations.length === 0 &&
        customEnterpriseSecurityConfigurations.length === 0 &&
        githubRecommendedConfiguration &&
        githubRecommendedConfiguration.repositories_count === 0,
      ),
    [customSecurityConfigurations, customEnterpriseSecurityConfigurations, githubRecommendedConfiguration],
  )

  // Hide upsell components when showing blankslate (org hasn't set up configurations yet)
  // In quick setup mode, hasNoConfigs triggers the blankslate
  const isShowingQuickSetupBlankslate = isQuickSetupEnabled && hasNoConfigs

  // Show banner for trial and volume_contact_sales (gated behind the ghas_config_usage_cards feature flag)
  const shouldShowUpsellBanner =
    isUsageSummaryEnabled && showUpsellBanner && (upsellType === 'trial' || upsellType === 'volume_contact_sales')
  // Always show CTA if there's an upsell type (gated behind the same feature flag)
  const shouldShowUpsellCTA = isUsageSummaryEnabled && !!upsellType

  const [licenses, setLicenses] = useState<OrganizationLicensePayload>(initialLicenses)

  const repositoryContextValue = useMemo(
    () => ({
      repositories,
      setRepositories,
      totalRepositoryCount,
      setTotalRepositoryCount,
      licenses,
      setLicenses,
    }),
    [repositories, setRepositories, totalRepositoryCount, setTotalRepositoryCount, licenses, setLicenses],
  )

  const isBundled = capabilities.advancedSecurity.bundled

  // Map coverage stats from backend to UsageSummary sections (enterprise admins only)
  const usageSummarySections = useMemo(() => {
    if (!coverageStats || coverageStats.length === 0) {
      return null
    }
    return coverageStats.map(stat => ({
      title: getDisplayTitle(stat.title, isBundled),
      percentage: stat.enabledPercentage,
      href: orgSecurityCoveragePath({
        org: organization,
        query: COVERAGE_QUERY_FILTER,
      }),
    }))
  }, [coverageStats, isBundled, organization])

  // Hide usage summary cards when showing blankslate (no configurations set up yet)
  const shouldShowUsageSummary = isUsageSummaryEnabled && usageSummarySections && !isShowingQuickSetupBlankslate

  const allSecurityProductsUnavailable = Object.values(securityProducts).every(
    product => product.availability === SecurityProductAvailability.Unavailable,
  )

  // Determine the BlankSlate Content
  const blankSlateProps = useMemo(() => {
    if (allSecurityProductsUnavailable) {
      return {
        header: 'No security features installed',
        message: 'Your GitHub Enterprise instance does not have any security features installed. ',
        url: docsUrls.installSecurityProducts,
        linkText: 'Learn about installing security features on GitHub Enterprise',
      }
    }

    if (configs.length === 0 && customEnterpriseSecurityConfigurations.length === 0) {
      return {
        header: 'Protect your code with Advanced Security configurations',
        message:
          'Enable and disable security features for specific repositories, ensure compliance, and manage your GitHub Advanced Security licenses with ',
        url: docsUrls.createConfig,
        linkText: 'security configurations',
        newConfigButtonPath: settingsOrgSecurityConfigurationsNewPath({org: organization}),
      }
    }

    return null
  }, [
    allSecurityProductsUnavailable,
    configs.length,
    customEnterpriseSecurityConfigurations.length,
    docsUrls.installSecurityProducts,
    docsUrls.createConfig,
    organization,
  ])

  const debouncedRefresh = useDebounce(
    useCallback(async () => {
      const repositoryIds = repositories.map(({id}) => id)
      const result = await fetchRefresh(organization, repositoryIds)

      // Update the configurations if the fetch was successful
      if (result) {
        const updatedGithubRecommendedConfiguration = result.githubRecommendedConfiguration as
          | MiniSecurityConfiguration
          | undefined
        const updatedSecurityConfigurations = result.customSecurityConfigurations
        const updatedCustomEnterpriseSecurityConfigurations = result.customEnterpriseSecurityConfigurations

        // Update the repositories_count for GitHub recommended configuration
        if (updatedGithubRecommendedConfiguration) {
          setGithubRecommendedConfiguration(prevConfig => {
            if (prevConfig) {
              return {
                ...prevConfig,
                repositories_count: updatedGithubRecommendedConfiguration.repositories_count,
              }
            }
          })
        }

        // Update the custom security configurations:
        if (updatedSecurityConfigurations) setCustomSecurityConfigurations(updatedSecurityConfigurations)
        if (updatedCustomEnterpriseSecurityConfigurations)
          setCustomEnterpriseSecurityConfigurations(updatedCustomEnterpriseSecurityConfigurations)

        // This needs to specifically check for undefined because we want to update the state if result.inProgress is true or false
        if (result.inProgress !== undefined) {
          if (result.inProgress) {
            setChangesInProgress(prev => ({
              ...prev,
              inProgress: result.inProgress,
              type: result.type,
            }))
          } else {
            setChangesInProgress({inProgress: false})
          }
        }

        if (result.repositories) {
          setRepositories(prevRepositories => {
            const updatedRepositories = [...prevRepositories]

            for (const updatedRepo of result.repositories) {
              const index = updatedRepositories.findIndex(repo => repo.id === updatedRepo.id)
              if (index !== -1) {
                updatedRepositories[index] = {...updatedRepositories[index], ...updatedRepo}
              } else {
                updatedRepositories.push(updatedRepo)
              }
            }

            return updatedRepositories
          })
        }

        if (result.failureCounts) setFailureCounts(result.failureCounts)

        if (result.licenses?.failedToFetchLicenses !== undefined && !result.licenses.failedToFetchLicenses) {
          setLicenses(result.licenses)
        }

        await refreshRepositories(queryState)
      }
    }, [refreshRepositories, organization, queryState, repositories, setRepositories]),
    1500,
    {leading: true, trailing: true},
  )

  const handleAliveEvent = useCallback(() => {
    debouncedRefresh()
  }, [debouncedRefresh])

  useAlive(channel, handleAliveEvent)

  const inProgressText =
    changesInProgress.type === 'enablement_changes'
      ? `Another enablement event is in progress. This may take a while and applying or editing configurations \
  will be unavailable until all repositories have been updated.`
      : 'Updating settings for repositories. This may take a while and applying or editing configurations\
  will be unavailable until all repositories have been updated.'

  const infoBannerText =
    'This organization does not have GitHub Advanced Security, which is free for public repositories and \
    billed per active committer for private and internal repositories. To apply configurations with GitHub \
    Advanced Security features to private repositories, '
  const infoBannerLinkText = 'upgrade to GitHub Advanced Security.'

  const handleDismiss = async (noticeName: string, setState: (state: boolean) => void) => {
    const result = await verifiedFetch(dismissNoticePath({notice: noticeName}), {
      method: 'POST',
    })

    if (result.ok) setState(false)
  }

  // Handle upsell banner dismissal (uses enterprise-level dismissal)
  const handleUpsellBannerDismiss = useCallback(async () => {
    if (!enterprise?.id || !upsellType) return

    const noticeKey = getUpsellBannerNoticeKey(upsellType)

    try {
      const result = await verifiedFetch(dismissBusinessNoticePath({notice: noticeKey, businessId: enterprise.id}), {
        method: 'POST',
      })
      if (result.ok) {
        setShowUpsellBanner(false)
      }
    } catch {
      // Silently handle network errors - banner stays visible but user can retry
    }
  }, [enterprise, upsellType])

  const enterpriseConfigurationsTableHasConfiguration =
    customEnterpriseSecurityConfigurations.length > 0 || initialGithubRecommendedConfiguration

  // we are setting reloadDocument since we need to trigger a full page load to switch the nav shell from Org to Enterprise
  const enterpriseAdminTip = (e: Enterprise) => {
    return (
      <span className={styles.Text}>
        <span className="text-bold">Tip:</span> As a {e.name} admin, you can{' '}
        <PrimerLink inline reloadDocument as={Link} to={settingsEnterpriseSecurityProductsPath({enterprise: e.slug})}>
          manage {organization} configurations in enterprise settings
        </PrimerLink>
        .
      </span>
    )
  }

  const handleOpenQuickSetup = useCallback((options: OpenQuickSetupOptions) => {
    setQuickSetupDialogState({
      isOpen: true,
      dialogMode: options.dialogMode,
      settingsReadOnly: options.settingsReadOnly,
      configurationId: options.configurationId,
      originalAttachedRepoCount: options.originalAttachedRepoCount,
      failedReposCount: options.failedReposCount,
    })
  }, [])

  const renderConfigurationsContent = () => (
    <>
      {enterpriseConfigsAvailable && capabilities.enterpriseOwned && enterprise && (
        <>
          {enterpriseConfigurationsTableHasConfiguration && (
            <>
              <SecurityConfigurationTable
                tableType="enterprise"
                header="Enterprise configurations"
                managedBy={`Managed by ${enterprise.name}`}
                onOpenQuickSetup={handleOpenQuickSetup}
                changesInProgress={changesInProgress}
                setChangesInProgress={setChangesInProgress}
                githubRecommendedConfiguration={githubRecommendedConfiguration}
                customSecurityConfigurations={customSecurityConfigurations}
                customEnterpriseSecurityConfigurations={customEnterpriseSecurityConfigurations}
              />
              {/* we should always render the box so that there is spacing between the two tables */}
              <div className={styles.Box}>{enterpriseAdmin && enterpriseAdminTip(enterprise)}</div>
            </>
          )}
        </>
      )}

      {(!enterpriseConfigsAvailable || (enterpriseConfigsAvailable && customSecurityConfigurations.length > 0)) && (
        <SecurityConfigurationTable
          tableType="organization"
          header={
            capabilities.enterpriseOwned && enterpriseConfigsAvailable
              ? 'Organization configurations'
              : 'Configurations'
          }
          onOpenQuickSetup={handleOpenQuickSetup}
          changesInProgress={changesInProgress}
          setChangesInProgress={setChangesInProgress}
          githubRecommendedConfiguration={githubRecommendedConfiguration}
          customSecurityConfigurations={customSecurityConfigurations}
          customEnterpriseSecurityConfigurations={customEnterpriseSecurityConfigurations}
        />
      )}

      {enterpriseConfigsAvailable &&
        capabilities.enterpriseOwned &&
        enterprise &&
        !enterpriseConfigurationsTableHasConfiguration &&
        enterpriseAdmin && <div className={styles.Box_1}>{enterpriseAdminTip(enterprise)}</div>}
    </>
  )

  const renderRepositoriesContent = () => (
    <RepositoryContext value={repositoryContextValue}>
      <RepositorySection
        setChangesInProgress={setChangesInProgress}
        configs={configs}
        failureCounts={failureCounts}
        executeQuery={searchRepositories}
        isQueryLoading={isQueryLoading}
        pageCount={pageCount}
        flashBannerType={flashBannerType}
        queryState={queryState}
      />
    </RepositoryContext>
  )

  const renderQuickSetupContent = () => {
    if (hasNoConfigs) {
      return (
        <Blankslate border data-testid="quick-setup-blankslate">
          <Blankslate.Heading>Set up Advanced Security</Blankslate.Heading>
          <Blankslate.Description>Manage Secret Protection, Code Security and Dependabot.</Blankslate.Description>
          <Blankslate.PrimaryAction href={settingsOrgSecurityConfigurationsQuickSetupPath({org: organization})}>
            Set up
          </Blankslate.PrimaryAction>
          <Blankslate.SecondaryAction href={docsUrls.aboutGHAS}>Learn more</Blankslate.SecondaryAction>
        </Blankslate>
      )
    }

    return (
      <>
        <UnderlineNav aria-label="Security configurations navigation" data-testid="quick-setup-nav">
          <UnderlineNav.Item
            as="button"
            aria-current={activeTab === 'configurations' ? 'page' : undefined}
            onSelect={() => switchTab('configurations')}
          >
            Configurations
          </UnderlineNav.Item>
          <UnderlineNav.Item
            as="button"
            aria-current={activeTab === 'repositories' ? 'page' : undefined}
            onSelect={() => switchTab('repositories')}
          >
            Repositories
          </UnderlineNav.Item>
        </UnderlineNav>

        {/* Render content based on active tab */}
        <div className="tmp-mt-3">
          {activeTab === 'configurations' && renderConfigurationsContent()}
          {activeTab === 'repositories' && renderRepositoriesContent()}
        </div>
      </>
    )
  }

  return (
    <>
      {quickSetupDialogState.isOpen && (
        <QuickSetupDialog
          onClose={() => {
            setQuickSetupDialogState(prev => ({...prev, isOpen: false, settingsReadOnly: false}))
            debouncedRefresh()
          }}
          org={organization}
          dialogMode={quickSetupDialogState.dialogMode}
          configurationId={quickSetupDialogState.configurationId}
          originalAttachedRepoCount={quickSetupDialogState.originalAttachedRepoCount}
          settingsReadOnly={quickSetupDialogState.settingsReadOnly}
          failedReposCount={quickSetupDialogState.failedReposCount}
        />
      )}
      {changesInProgress.inProgress && <Banner bannerText={inProgressText} bannerType="inprogress" />}
      <Subhead
        hideDivider={isQuickSetupEnabled}
        description={
          isQuickSetupEnabled
            ? undefined
            : 'Define and apply security configurations to make sure your repositories are protected.'
        }
        organization={organization}
        newConfigButton={!(isQuickSetupEnabled && hasNoConfigs)}
        allSecurityProductsUnavailable={allSecurityProductsUnavailable}
        onOpenQuickSetup={
          isQuickSetupEnabled
            ? () => {
                setQuickSetupDialogState({isOpen: true, dialogMode: QuickSetupDialogMode.NEW, settingsReadOnly: false})
              }
            : undefined
        }
      >
        {isQuickSetupEnabled ? 'Advanced Security' : 'Security configurations'}
      </Subhead>
      <UsageLockedBanner capabilities={capabilities} userNamespace={false} />
      {blankSlateProps ? (
        <BlankSlate {...blankSlateProps} />
      ) : (
        <>
          {/* Enterprise admin upsell banner (dismissible) */}
          {shouldShowUpsellBanner && upsellType && (
            <div className={styles.UpsellBanner}>
              <UpsellBanner
                upsellType={upsellType}
                selfServeTrialInfo={selfServeTrialInfo}
                onDismiss={handleUpsellBannerDismiss}
              />
            </div>
          )}
          {/* Enterprise admin usage summary cards - hidden when showing blankslate */}
          {shouldShowUsageSummary && (
            <UsageSummary
              sections={usageSummarySections}
              className={shouldShowUpsellCTA ? usageSummaryStyles.containerWithCTA : undefined}
            />
          )}
          {/* Enterprise admin upsell CTA */}
          {shouldShowUpsellCTA && upsellType && (
            <div className={styles.UpsellCTAWithSummary}>
              <UpsellCTA upsellType={upsellType} selfServeTrialInfo={selfServeTrialInfo} />
            </div>
          )}
          {showInfoBanner && (
            <Banner
              bannerText={infoBannerText}
              linkText={infoBannerLinkText}
              linkHref={docsUrls.ghasTrial}
              onDismiss={() => {
                handleDismiss('security_configurations_non_ghas_org_info', setShowInfoBanner)
              }}
              dismissible
              bannerType="info"
            />
          )}

          {/* the controller will hide the talk to us banner if we are showing the info banner above */}
          {/* but we do want to hide the banner if are in the onboarding flow */}
          {searchParams.get('tip') === 'recommended_settings' ? (
            <OnboardingTipBanner
              link={orgOnboardingAdvancedSecurityPath({org: organization})}
              icon={ShieldCheckIcon}
              linkText="Back to onboarding"
              heading="Enable Advanced Security with GitHub recommended configuration"
            >
              Automatically apply our standard settings to Dependabot, code scanning, and secret scanning by selecting{' '}
              <strong> Apply to</strong> below.
            </OnboardingTipBanner>
          ) : (
            selfServeBanner && (
              <div className="tmp-mb-3" data-testid="self-serve-banner">
                <CopilotSurvey {...selfServeBanner} />
              </div>
            )
          )}

          {/* Conditional rendering based on quick set up feature flag */}
          {isQuickSetupEnabled ? (
            renderQuickSetupContent()
          ) : (
            /* Original layout when quick set up feature flag is disabled */
            <>
              {renderConfigurationsContent()}
              {renderRepositoriesContent()}
            </>
          )}
        </>
      )}
    </>
  )
}

export default OrganizationSettingsSecurityProducts
