import {useState, useCallback} from 'react'
import {Button} from '@primer/react'
import {Link} from '@github-ui/react-core/link'
import {useNavigate} from '@github-ui/use-navigate'
import {settingsOrgSecurityProductsPath, settingsOrgSecurityConfigurationsNewPath} from '@github-ui/paths'
import {useAppContext} from '../contexts/AppContext'
import Subhead from '../components/Subhead'
import {SettingsStep} from '../components/QuickSetup/SettingsStep'
import {ReviewStep} from '../components/QuickSetup/ReviewStep'
import {useQuickSetupForm} from '../hooks/use-quick-setup-form'
import {useAdditionalLicenseUsage} from '../hooks/use-additional-license-usage'
import {determineLicenseCounts} from '../utils/determine-license-counts'
import {useSelectedLicenseCounts} from '../hooks/use-selected-license-counts'
import {
  QuickSetupDialogMode,
  QuickSetupApplyTo,
  QuickSetupDefaultForNewRepos,
} from '../security-products-enablement-types'
import type {QuickSetupFormState} from '../security-products-enablement-types'
import styles from './FirstConfigSetupPage.module.css'

type Step = 'settings' | 'review'

export default function FirstConfigSetupPage() {
  const {organization} = useAppContext()
  const navigate = useNavigate()

  const listConfigsLink = settingsOrgSecurityProductsPath({org: organization})
  const customConfigLink = settingsOrgSecurityConfigurationsNewPath({org: organization})

  const {
    formState,
    setFormState,
    handleSave,
    isSaving,
    isSaveError,
    // Repository picker state bundled for prop threading
    repositoryPicker,
  } = useQuickSetupForm({
    org: organization,
    onSuccess: () => navigate(listConfigsLink),
    dialogMode: QuickSetupDialogMode.NEW,
    isFirstConfig: true,
  })

  // Calculate license counts for selected repositories
  const {selectedSecretProtectionCount, selectedCodeSecurityCount} = useSelectedLicenseCounts({
    selectedRepoIds: formState.selectedRepoIds,
    reposById: repositoryPicker.reposById,
  })

  // Fetch additional license usage for "Apply to all" scenario
  const {
    licenseUsage: allReposLicenseUsage,
    isLoading: isLoadingAllReposLicenses,
    isError: isAllReposLicensesError,
    refetch: refetchAllReposLicenses,
  } = useAdditionalLicenseUsage({
    org: organization,
    enabled: formState.applyTo === QuickSetupApplyTo.All,
  })

  // Loading/error states only apply when "Apply to all" is selected
  const isLoadingLicenses = formState.applyTo === QuickSetupApplyTo.All && isLoadingAllReposLicenses
  const isLicensesError = formState.applyTo === QuickSetupApplyTo.All && isAllReposLicensesError

  // Determine license counts for review step (uses API data for "All", calculated data for "Selected")
  const {repoCount, secretProtectionCount, codeSecurityCount} = determineLicenseCounts({
    formState,
    forAllRepos: {
      repoCount: repositoryPicker.totalCount,
      licenseUsage: allReposLicenseUsage,
    },
    forSelectedRepos: {
      repoCount: formState.selectedRepoIds.size,
      secretProtectionCount: selectedSecretProtectionCount,
      codeSecurityCount: selectedCodeSecurityCount,
    },
  })

  // Handler for repository selection changes
  const handleSelectionChange = useCallback(
    (ids: Set<number>) => {
      setFormState(prev => ({...prev, selectedRepoIds: ids}))
    },
    [setFormState],
  )

  // Sync defaultForNewRepos with applyTo changes for page view
  const handleFormStateChange = useCallback(
    (newState: QuickSetupFormState) => {
      // Only set defaultForNewRepos when the repository applyTo scope changes
      if (newState.applyTo !== formState.applyTo) {
        const updatedState = {
          ...newState,
          defaultForNewRepos:
            newState.applyTo === QuickSetupApplyTo.All
              ? QuickSetupDefaultForNewRepos.All
              : QuickSetupDefaultForNewRepos.None,
        }
        setFormState(updatedState)
      } else {
        setFormState(newState)
      }
    },
    [formState.applyTo, setFormState],
  )

  const [currentStep, setCurrentStep] = useState<Step>('settings')

  const renderContent = () => {
    switch (currentStep) {
      case 'settings':
        return (
          <SettingsStep
            formState={formState}
            onFormStateChange={handleFormStateChange}
            isLoading={false}
            isLoadError={false}
            repositoryPicker={repositoryPicker}
            onSelectionChange={handleSelectionChange}
          />
        )
      case 'review':
        return (
          <ReviewStep
            applyTo={formState.applyTo}
            defaultForNewRepos={formState.defaultForNewRepos}
            repoCount={repoCount}
            secretProtectionCount={secretProtectionCount}
            codeSecurityCount={codeSecurityCount}
            isSaveError={isSaveError}
            isLoadingLicenses={isLoadingLicenses}
            isLicensesError={isLicensesError}
            onRetryLicenses={refetchAllReposLicenses}
          />
        )
    }
  }

  const renderFooterButtons = () => {
    switch (currentStep) {
      case 'settings':
        return (
          <div className={styles.footerButtons}>
            <Button variant="primary" onClick={() => setCurrentStep('review')}>
              Review
            </Button>
            <Button variant="invisible" as={Link} to={customConfigLink}>
              Custom configuration
            </Button>
          </div>
        )
      case 'review':
        return (
          <div className={styles.footerButtons}>
            <Button variant="primary" onClick={handleSave} disabled={isSaving}>
              Save and apply
            </Button>
            <Button onClick={() => setCurrentStep('settings')}>Back</Button>
            <Button onClick={() => navigate(listConfigsLink)}>Cancel</Button>
          </div>
        )
    }
  }

  return (
    <>
      <Subhead>Set up Advanced Security</Subhead>

      {/* Main content */}
      <div className="p-responsive" data-hpc>
        {renderContent()}

        {/* Footer buttons */}
        {renderFooterButtons()}
      </div>
    </>
  )
}
