import {InfoIcon} from '@primer/octicons-react'
import {ApplyToDropdown} from './ApplyToDropdown'
import type {QuickSetupApplyTo} from '../../../security-products-enablement-types'
import styles from '../SettingsStep.module.css'

interface ApplyToSectionLargeConfigProps {
  applyTo: QuickSetupApplyTo
  onApplyToChange: (value: QuickSetupApplyTo) => void
}

/**
 * Apply To section for the dialog flow when a configuration is attached to >500 repos.
 * Shows dropdown with NotApplicable option and info message directing users
 * to manage repositories via the repositories tab.
 *
 */
export function ApplyToSectionLargeConfig({applyTo, onApplyToChange}: ApplyToSectionLargeConfigProps) {
  return (
    <div className={styles.applyToSettingRow}>
      <ApplyToDropdown applyTo={applyTo} onApplyToChange={onApplyToChange} variant="largeConfig" />
      <div className={styles.largeConfigInfoMessage} role="status">
        <div className="pt-1">
          <InfoIcon size={16} className="flex-shrink-0" aria-hidden="true" />
        </div>
        <div>
          <span className="text-bold">This configuration is applied to over 500 repositories.</span>{' '}
          <span>Use the repositories tab to manage repositories.</span>
        </div>
      </div>
    </div>
  )
}
