import {QuickSetupApplyTo, QuickSetupSettingValue} from '../security-products-enablement-types'
import type {LicenseUsage, QuickSetupFormState} from '../security-products-enablement-types'

/**
 * Apply SKU filtering to license counts.
 * Returns 0 for disabled SKUs since they don't require licenses.
 */
export function applySkuEnablementFiltering(
  counts: {secretProtectionCount: number; codeSecurityCount: number},
  formState: Pick<QuickSetupFormState, 'secretProtection' | 'codeSecurity'>,
) {
  return {
    secretProtectionCount:
      formState.secretProtection === QuickSetupSettingValue.Disabled ? 0 : counts.secretProtectionCount,
    codeSecurityCount: formState.codeSecurity === QuickSetupSettingValue.Disabled ? 0 : counts.codeSecurityCount,
  }
}

interface ForAllReposCounts {
  repoCount: number
  licenseUsage: LicenseUsage
}

interface ForSelectedReposCounts {
  repoCount: number
  secretProtectionCount: number
  codeSecurityCount: number
}

/**
 * Determine license counts for the ReviewStep component.
 *
 * applyTo behavior:
 * - "All": uses API-provided counts from forAllRepos
 * - "Selected": uses calculated counts from forSelectedRepos
 * - "NotApplicable": uses originalAttachedRepoCount for repo count (license counts from forSelectedRepos)
 * - "None": returns 0 for all counts
 *
 * SKU filtering:
 * - If secretProtection is "disabled", secretProtectionCount is 0
 * - If codeSecurity is "disabled", codeSecurityCount is 0
 * - "enabled", "not_set", or "custom" require licenses
 */
export function determineLicenseCounts({
  formState,
  forAllRepos,
  forSelectedRepos,
  originalAttachedRepoCount,
}: {
  formState: Pick<QuickSetupFormState, 'applyTo' | 'secretProtection' | 'codeSecurity'>
  forAllRepos: ForAllReposCounts
  forSelectedRepos: ForSelectedReposCounts
  originalAttachedRepoCount?: number
}) {
  const {applyTo, secretProtection, codeSecurity} = formState

  let baseCounts: {repoCount: number; secretProtectionCount: number; codeSecurityCount: number}

  switch (applyTo) {
    case QuickSetupApplyTo.None:
      return {
        repoCount: 0,
        secretProtectionCount: 0,
        codeSecurityCount: 0,
      }
    case QuickSetupApplyTo.All:
      baseCounts = {
        repoCount: forAllRepos.repoCount,
        secretProtectionCount: forAllRepos.licenseUsage.secret_protection.license_count,
        codeSecurityCount: forAllRepos.licenseUsage.code_security.license_count,
      }
      break
    case QuickSetupApplyTo.Selected:
      baseCounts = {
        repoCount: forSelectedRepos.repoCount,
        secretProtectionCount: forSelectedRepos.secretProtectionCount,
        codeSecurityCount: forSelectedRepos.codeSecurityCount,
      }
      break
    case QuickSetupApplyTo.NotApplicable:
      // License counts aren't displayed for NotApplicable (ReviewStep hides the estimates section)
      baseCounts = {
        repoCount: originalAttachedRepoCount ?? 0,
        secretProtectionCount: 0,
        codeSecurityCount: 0,
      }
      break
    default: {
      const exhaustiveCheck: never = applyTo
      throw new Error(`Unhandled applyTo case: ${exhaustiveCheck}`)
    }
  }

  // Apply SKU filtering: disabled SKUs don't require licenses
  const filtered = applySkuEnablementFiltering(baseCounts, {secretProtection, codeSecurity})
  return {
    repoCount: baseCounts.repoCount,
    ...filtered,
  }
}
