import type {PathFunction} from '@github-ui/paths'
import type {UpsellType} from '../security-products-enablement-types'

// Notice keys for banner dismissal - must match backend constants in security_analysis_controller.rb
export const SELF_SERVE_GHAS_UPSELL_BANNER_NOTICE = 'self_serve_ghas_upsell_banner_in_configs'
export const VOLUME_GHAS_UPSELL_BANNER_NOTICE = 'volume_ghas_upsell_banner_in_configs'

export function getUpsellBannerNoticeKey(upsellType: UpsellType): string {
  return upsellType === 'trial' ? SELF_SERVE_GHAS_UPSELL_BANNER_NOTICE : VOLUME_GHAS_UPSELL_BANNER_NOTICE
}

export const dismissNoticePath: PathFunction<{notice: string}> = ({notice}) => `/settings/dismiss-notice/${notice}`

export const dismissBusinessNoticePath: PathFunction<{notice: string; businessId: number}> = ({notice, businessId}) =>
  `/growth/notice_dismissals?notice=${encodeURIComponent(notice)}&business_id=${businessId}`

export const dismissFailureBannerPath: PathFunction<{org: string}> = ({org}) =>
  `/organizations/${org}/settings/security_products/dismiss_failure_banner`
