import pluralize from 'pluralize'
import {useAppContext} from '../../contexts/AppContext'
import styles from './QuickSetupDialog.module.css'

interface FooterLicenseCountsProps {
  secretProtectionCount: number
  codeSecurityCount: number
}

/**
 * Displays license counts in dialog footers.
 */
export function FooterLicenseCounts({secretProtectionCount, codeSecurityCount}: FooterLicenseCountsProps) {
  const {capabilities} = useAppContext()

  // Determine which license counts to show based on org capabilities
  const showLicenseCounts = !capabilities.advancedSecurity.bundled
  const showSecretProtectionLicenses = showLicenseCounts && capabilities.advancedSecurity.secretProtectionPurchased
  const showCodeSecurityLicenses = showLicenseCounts && capabilities.advancedSecurity.codeSecurityPurchased

  return (
    <div className={styles.licenseCounts}>
      {showSecretProtectionLicenses && (
        <div className="color-fg-muted text-small">
          {secretProtectionCount} additional Secret Protection {pluralize('license', secretProtectionCount, false)}{' '}
          required
        </div>
      )}
      {showCodeSecurityLicenses && (
        <div className="color-fg-muted text-small">
          {codeSecurityCount} additional Code Security {pluralize('license', codeSecurityCount, false)} required
        </div>
      )}
    </div>
  )
}
