import {Blankslate} from '@primer/react/experimental'
import {BypassSelectPanel} from '../bypassSelectPanel/BypassSelectPanel'
import {BypassList} from '../bypassList/BypassList'
import {Text} from '@primer/react'
import styles from './BypassManager.module.css'
import {clsx} from 'clsx'
import {AlertIcon} from '@primer/octicons-react'
import {ActorBypassMode, type SupportedBypassMode, type BypassActor} from '../../bypass-actors-types'

type AddBypassActor = (
  actorId: BypassActor['actorId'],
  actorType: BypassActor['actorType'],
  preferredAvatarUrl: BypassActor['preferredAvatarUrl'],
  name: BypassActor['name'],
  bypassMode: BypassActor['bypassMode'],
  owner: BypassActor['owner'],
) => void

type UpdateBypassActor = (bypassActor: BypassActor) => void

type RemoveBypassActor = (bypassActor: BypassActor) => void

export interface BypassManagerProps {
  bypassers: BypassActor[]
  baseAvatarUrl: string
  suggestedBypassReviewersUrl: string
  addBypassActor?: AddBypassActor
  updateBypassActor: UpdateBypassActor
  removeBypassActor: RemoveBypassActor
  noSideMargins?: boolean
}

const pluralizeActors = (count: number) => `${count === 1 ? 'actor' : 'actors'}`

// This component brings the other components together into a view with a "Select Actors" button, a header, and a list.
export const BypassManager: React.FC<BypassManagerProps> = ({
  bypassers,
  baseAvatarUrl,
  suggestedBypassReviewersUrl,
  addBypassActor,
  updateBypassActor,
  removeBypassActor,
  noSideMargins,
}) => {
  const supportedBypassModes: SupportedBypassMode[] = [
    {
      mode: ActorBypassMode.ALWAYS,
      description: 'Push Protection will run and the selected actor(s) will be prompted to bypass',
    },
    {
      mode: ActorBypassMode.EXEMPT,
      description: 'Push Protection will not run and no bypass prompt will be shown',
    },
  ]

  return (
    <>
      <div className={clsx(styles.Box, !noSideMargins && styles.WithSideMargins)}>
        <div className={clsx('Box-header', styles.Box_1)}>
          <Text weight="semibold">{`${bypassers.length || 0} ${pluralizeActors(bypassers.length)}`}</Text>
          {addBypassActor && (
            <BypassSelectPanel
              title={'Select actors'}
              baseAvatarUrl={baseAvatarUrl}
              enabledBypassActors={bypassers}
              addBypassActor={addBypassActor}
              removeBypassActor={removeBypassActor}
              suggestionsUrl={suggestedBypassReviewersUrl}
              addReviewerSubtitle={''}
            />
          )}
        </div>
        {bypassers.length > 0 ? (
          <ul>
            <BypassList
              supportedBypassModes={supportedBypassModes}
              enabledBypassActors={bypassers}
              updateBypassActor={updateBypassActor}
              removeBypassActor={removeBypassActor}
              baseAvatarUrl={baseAvatarUrl}
            />
          </ul>
        ) : (
          <Blankslate>
            <Blankslate.Heading>No actors have been selected</Blankslate.Heading>
          </Blankslate>
        )}
      </div>
      {bypassers.length === 0 && (
        <div className={styles.Box_2}>
          <AlertIcon className="mr-2 border-none fgColor-attention" aria-label="No actors have been selected" />
          <span className={styles.Text}>At least one actor is required.</span>
        </div>
      )}
    </>
  )
}
